#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"
#include "gui_forms/types.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// PropertyList's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/property_list.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks and,
// where C# lets a subclass rewrite the value, the protected virtual coerce
// hook), the compare and store, then the written hook (the touch, side
// effects and the change event, through the protected virtual
// on_<property>_changed() where Windows Forms has OnXChanged). A read is
// `(*control).x.read()`.

// The header content's height, 0 to 4096 (std::invalid_argument otherwise; nonzero needs header content); a view onto the list's layout. A change re-lays out the rows.
template <typename Declaring>
struct PropertyListHeaderHeightCapability {
    PropertyView<double, PropertyListHeaderHeightCapability<Declaring>> header_height;

    static void assign(PropertyListHeaderHeightCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.header_height), std::move(incoming));
    }

    static double read(const PropertyListHeaderHeightCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        double current = control.read_view(capability.header_height);
        return current;
    }
};

// The label column's width, 40 to 320 (std::invalid_argument otherwise); a view onto the list's layout. A change re-lays out the rows.
template <typename Declaring>
struct PropertyListLabelWidthCapability {
    PropertyView<double, PropertyListLabelWidthCapability<Declaring>> label_width;

    static void assign(PropertyListLabelWidthCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.label_width), std::move(incoming));
    }

    static double read(const PropertyListLabelWidthCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        double current = control.read_view(capability.label_width);
        return current;
    }
};

// The rows' font (Font); a view onto the list's typography, which follows the theme until written. A write marks the font as set from code, passes it to the editors and re-lays out; an invalid FontSpec throws std::invalid_argument.
template <typename Declaring>
struct PropertyListFontCapability {
    PropertyView<FontSpec, PropertyListFontCapability<Declaring>> font;

    static void assign(PropertyListFontCapability& capability, FontSpec incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.font), std::move(incoming));
    }

    static FontSpec read(const PropertyListFontCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        FontSpec current = control.read_view(capability.font);
        return current;
    }
};

// Each row's height, above 0 and at most 4096 (std::invalid_argument otherwise); a view onto the list's layout. A change re-lays out the rows.
template <typename Declaring>
struct PropertyListRowHeightCapability {
    PropertyView<double, PropertyListRowHeightCapability<Declaring>> row_height;

    static void assign(PropertyListRowHeightCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.row_height), std::move(incoming));
    }

    static double read(const PropertyListRowHeightCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        double current = control.read_view(capability.row_height);
        return current;
    }
};

// How far the rows are scrolled; a view onto the list's scroll state. A write is clamped to the content's overflow; a value that is not finite throws std::invalid_argument.
template <typename Declaring>
struct PropertyListScrollOffsetCapability {
    PropertyView<double, PropertyListScrollOffsetCapability<Declaring>> scroll_offset;

    static void assign(PropertyListScrollOffsetCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.scroll_offset), std::move(incoming));
    }

    static double read(const PropertyListScrollOffsetCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        double current = control.read_view(capability.scroll_offset);
        return current;
    }
};

// Every PropertyList capability, in the order the declaring class takes them.
template <typename Declaring>
struct PropertyListCapabilities : public PropertyListHeaderHeightCapability<Declaring>,
                                  public PropertyListLabelWidthCapability<Declaring>,
                                  public PropertyListFontCapability<Declaring>,
                                  public PropertyListRowHeightCapability<Declaring>,
                                  public PropertyListScrollOffsetCapability<Declaring> {};

} // namespace gui_forms
